<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router';
import {useI18n} from 'vue-i18n';
import {operationRequest,type OperationRow} from '../../services/admin/operations';
import {clinicDate,timeLabel} from '../../services/booking/calendar';
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue';
const props=defineProps<{doctorId?:string;embedded?:boolean;workingHours?:Array<{weekday:number;start:string;end:string;effective_from?:string;effective_until?:string}>}>();
const {t,locale}=useI18n(),route=useRoute(),router=useRouter();
const mode=ref(props.embedded?'time-off':'schedules'),rows=ref<OperationRow[]>([]),doctors=ref<any[]>([]),services=ref<any[]>([]),doctor=ref(props.doctorId||(typeof route.query.doctor==='string'?route.query.doctor:'')),service=ref(''),date=ref(clinicDate()),slots=ref<any[]|null>(null);
const form=ref<any>(null),selected=ref<OperationRow|null>(null),busy=ref(false),error=ref(''),count=ref(0),status=ref('');
let controller=new AbortController(),snapshot='',key='';
const dateShift=(value:string,days:number)=>{const d=new Date(value+'T12:00:00Z');if(!Number.isFinite(d.getTime()))return '';d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)};
const firstDate=computed({get:()=>form.value?.start_local?.slice(0,10)||'',set:(v:string)=>{form.value.start_local=v+'T00:00'}});
const lastDate=computed({get:()=>dateShift(form.value?.end_local?.slice(0,10)||'',-1),set:(v:string)=>{form.value.end_local=dateShift(v,1)+'T00:00'}});
const quickKind=ref('');
const dirty=computed(()=>form.value&&JSON.stringify(form.value)!==snapshot);
const visible=computed(()=>rows.value.filter(r=>r.data.doctor_id===doctor.value));
const days=computed(()=>Array.from({length:7},(_,i)=>({value:i,label:new Intl.DateTimeFormat(locale.value,{weekday:'long',timeZone:'Europe/Riga'}).format(new Date(Date.UTC(2026,0,4+i,12)))})));
function discard(){return !dirty.value||window.confirm(t('operations.discard'))}
function local(iso:string){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Riga',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));const get=(k:string)=>parts.find(p=>p.type===k)!.value;return `${get('year')}-${get('month')}-${get('day')}T${get('hour')}:${get('minute')}`}
async function load(){controller.abort();controller=new AbortController();const own=controller;busy.value=true;error.value='';try{const [r,o]=await Promise.all([operationRequest('/operations/'+mode.value,own.signal),operationRequest('/operations/'+mode.value+'/options',own.signal)]);if(!own.signal.aborted){rows.value=r.items;doctors.value=o.doctors;services.value=o.services;if(!doctor.value)doctor.value=o.doctors[0]?.id||''}}catch{if(!own.signal.aborted)error.value='unavailable'}finally{if(!own.signal.aborted)busy.value=false}}
function edit(row?:OperationRow){if(!discard())return;quickKind.value='';selected.value=row||null;error.value='';status.value='';key=crypto.randomUUID();const d=row?.data;form.value=mode.value==='schedules'?{doctor_id:doctor.value,weekday:d?.weekday??1,start_time:d?.start_time?.slice(0,5)||'',end_time:d?.end_time?.slice(0,5)||'',effective_from:d?.effective_from?.slice(0,10)||'',effective_until:d?.effective_until?.slice(0,10)||'',active:d?.active??true}:{doctor_id:doctor.value,start_local:d?local(d.starts_at):'',end_local:d?local(d.ends_at):'',reason:d?.reason||'other',full_day:d?.full_day??false,active:d?.active??true};snapshot=JSON.stringify(form.value)}
async function switchMode(next:string){if(!discard())return;mode.value=next;form.value=null;slots.value=null;await load()}
async function changeDoctor(event:Event){const target=event.target as HTMLSelectElement;if(!discard()){target.value=doctor.value;return}doctor.value=target.value;form.value=null;slots.value=null;await router.replace({query:{...route.query,doctor:doctor.value}})}
async function save(){if(!form.value||busy.value)return;error.value='';if(mode.value==='time-off'&&(!form.value.start_local||!form.value.end_local||form.value.start_local>=form.value.end_local)){error.value='absenceRange';return}if(quickKind.value==='break'&&props.workingHours){const f=form.value,d=f.start_local.slice(0,10),weekday=new Date(d+'T12:00:00Z').getUTCDay();if(d!==f.end_local.slice(0,10)||!props.workingHours.some(h=>h.weekday===weekday&&h.start<=f.start_local.slice(11)&&h.end>=f.end_local.slice(11)&&(!h.effective_from||h.effective_from<=d)&&(!h.effective_until||h.effective_until>=d))){error.value='breakHours';return}}busy.value=true;const data={...form.value};if(mode.value==='schedules'){const minutes=(s:string)=>Number(s.slice(0,2))*60+Number(s.slice(3,5));data.start_minute=minutes(data.start_time);data.end_minute=minutes(data.end_time);delete data.start_time;delete data.end_time}try{await operationRequest('/operations/'+mode.value+(selected.value?'/'+selected.value.id:''),controller.signal,{operation_id:key,expected_version:selected.value?.version||'',data},selected.value?'PUT':'POST');form.value=null;slots.value=null;await load();status.value=t('operations.saved')}catch(e){const message=(e as Error).message;error.value=message==='invalid'?'absenceRange':['conflict','impact'].includes(message)?message:'unavailable';count.value=(e as any).count||0}finally{busy.value=false}}
async function quick(kind:string){if(!doctor.value||!discard())return;mode.value=kind==='hours'?'schedules':'time-off';form.value=null;await load();if(error.value)return;edit();quickKind.value=kind;if(kind!=='hours'){form.value.reason=kind==='vacation'?'vacation':'other';form.value.full_day=kind!=='break';if(form.value.full_day){const today=clinicDate(),next=new Date(today+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);form.value.start_local=today+'T00:00';form.value.end_local=next.toISOString().slice(0,10)+'T00:00'}snapshot=JSON.stringify(form.value)}}
async function preview(){slots.value=null;error.value='';busy.value=true;try{const result=await operationRequest(`/operations/schedules/preview?service_id=${service.value}&doctor_id=${doctor.value}&date=${date.value}`,controller.signal);slots.value=result.slots}catch{error.value='unavailable'}finally{busy.value=false}}
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}window.addEventListener('beforeunload',unload);onBeforeRouteLeave(()=>discard());onBeforeRouteUpdate(()=>discard());watch(()=>route.query.doctor,value=>{if(!props.embedded&&typeof value==='string'){doctor.value=value;form.value=null;slots.value=null}});onBeforeUnmount(()=>{controller.abort();window.removeEventListener('beforeunload',unload)});void load();
defineExpose({dirty});
</script>
<template>
<section class="schedules"><AdminPageHeader :level="embedded?'h2':'h1'" :title="t(embedded?'operations.timeOff':'operations.schedule')"><template #actions><button v-for="action in (embedded?['break','blockDay','vacation']:['hours','break','blockDay','vacation'])" :key="action" :disabled="busy||!doctor" @click="quick(action)">{{t('simple.'+(action==='hours'?'editHours':action))}}</button></template></AdminPageHeader>
<p>{{t('operations.riga')}}</p><p role="status">{{busy?t('operations.loading'):status}}</p><p v-if="error" role="alert">{{t(['absenceRange','breakHours'].includes(error)?'specialist.'+error:'operations.'+error,{count})}}</p>
<p v-if="!busy&&!error&&!doctors.length">{{t('operations.noDoctors')}} <RouterLink to="/admin/doctors/booking">{{t('operations.doctors')}}</RouterLink></p>
<label v-if="!embedded">{{t('operations.doctorName')}}<select :aria-label="t('operations.doctorName')" :value="doctor" :disabled="busy" @change="changeDoctor"><option value="" disabled>{{t('operations.choose')}}</option><option v-for="d in doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label>
<p v-if="doctor&&!embedded"><RouterLink :to="'/admin/doctors/manage/'+doctor" target="_blank">{{t('operations.doctorName')}}</RouterLink></p>
<div v-if="mode==='schedules'" class="week-preview"><section v-for="day in days" :key="day.value"><h3>{{day.label}}</h3><p v-for="row in visible.filter(r=>r.data.weekday===day.value&&r.data.active)" :key="row.id">{{row.data.start_time.slice(0,5)}}–{{row.data.end_time.slice(0,5)}}</p><button :aria-label="t('operations.create')+' · '+day.label" :disabled="!doctor||busy" @click="()=>{edit();if(form)form.weekday=day.value}">{{t('operations.create')}}</button></section></div>
<div v-if="!embedded" class="actions"><button :aria-pressed="mode==='schedules'" :disabled="busy" @click="switchMode('schedules')">{{t('operations.weekly')}}</button><button :aria-pressed="mode==='time-off'" :disabled="busy" @click="switchMode('time-off')">{{t('operations.timeOff')}}</button><button :disabled="!doctor||busy||!!error" @click="edit()">{{t('operations.create')}}</button><button :disabled="busy" @click="load">{{t('operations.refresh')}}</button></div>
<p v-if="!visible.length&&!busy&&!error">{{t('operations.empty')}}</p>
<div class="schedule-grid"><ul><li v-for="row in visible" :key="row.id"><button @click="edit(row)"><template v-if="mode==='schedules'">{{days[row.data.weekday]?.label}} · {{row.data.start_time.slice(0,5)}}–{{row.data.end_time.slice(0,5)}}</template><template v-else>{{local(row.data.starts_at).replace('T',' ')}} — {{local(row.data.ends_at).replace('T',' ')}}</template><span v-if="!row.data.active"> · {{t('operations.archived')}}</span></button></li></ul>
<form v-if="form" :inert="busy" @submit.prevent="save"><template v-if="mode==='schedules'"><label>{{t('operations.weekday')}}<select :aria-label="t('operations.weekday')" v-model.number="form.weekday"><option v-for="day in days" :key="day.value" :value="day.value">{{day.label}}</option></select></label><label>{{t('operations.start')}}<input v-model="form.start_time" type="time" required/></label><label>{{t('operations.end')}}<input v-model="form.end_time" type="time" required/></label><label>{{t('operations.effectiveFrom')}}<input v-model="form.effective_from" type="date"/></label><label>{{t('operations.effectiveUntil')}}<input v-model="form.effective_until" type="date"/></label></template>
<template v-else><template v-if="form.full_day"><label>{{t('operations.start')}}<input v-model="firstDate" type="date" required/></label><label>{{t('operations.end')}}<input v-model="lastDate" type="date" required/></label></template><template v-else><label>{{t('operations.start')}}<input v-model="form.start_local" type="datetime-local" required/></label><label>{{t('operations.end')}}<input v-model="form.end_local" type="datetime-local" required/></label></template><label>{{t('operations.reason')}}<select :aria-label="t('operations.reason')" v-model="form.reason"><option v-for="reason in ['holiday','vacation','other']" :key="reason" :value="reason">{{t('operations.'+reason)}}</option></select></label><label><input v-model="form.full_day" type="checkbox" @change="()=>{if(form.full_day){const first=form.start_local?.slice(0,10)||clinicDate(),last=form.end_local?.slice(0,10)||first;form.start_local=first+'T00:00';form.end_local=dateShift(last,1)+'T00:00'}}"/>{{t('operations.fullDay')}}</label></template>
<label><input v-model="form.active" type="checkbox"/>{{t('operations.active')}}</label><p>{{t('operations.impactHelp')}}</p><div class="actions"><button type="submit">{{t('operations.save')}}</button><button type="button" @click="()=>{if(discard())form=null}">{{t('operations.cancel')}}</button></div></form></div>
<details class="availability-options" :open="!embedded"><summary v-if="embedded">{{t('operations.previewAvailability')}}</summary><form class="availability-preview" @submit.prevent="preview"><h2 v-if="!embedded">{{t('operations.previewAvailability')}}</h2><p v-if="!busy&&!error&&!services.length">{{t('operations.previewSetup')}}</p><label>{{t('operations.services')}}<select :aria-label="t('operations.services')" v-model="service" required><option value="" disabled>{{t('operations.choose')}}</option><option v-for="s in services" :key="s.id" :value="s.id">{{s['name_'+locale]}}</option></select></label><label>{{t('operations.date')}}<input v-model="date" type="date" required/></label><button :disabled="busy||!doctor||!service">{{t('operations.previewAvailability')}}</button><p v-if="slots?.length===0">{{t('operations.noSlots')}}</p><ul v-if="slots?.length"><li v-for="slot in slots" :key="slot.starts_at">{{timeLabel(slot.starts_at,locale)}}–{{timeLabel(slot.ends_at,locale)}}</li></ul></form></details>
</section>
</template>
<style scoped>
.week-preview{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:12px;margin:24px 0}.week-preview section{border-top:1px solid var(--line);padding-top:12px}.week-preview h3{font:inherit}.schedules{max-width:1150px}.schedules p a{text-decoration:underline;text-underline-offset:3px}.schedules p{line-height:1.7;max-width:80ch}.schedules label{display:block;margin:14px 0}.schedules input:not([type=checkbox]),.schedules select{display:block;min-height:44px;width:100%;padding:10px;border:1px solid var(--line);background:var(--white);color:var(--ink);font:inherit}.schedules button{font:inherit;min-height:44px;padding:10px 16px;border:1px solid var(--line);background:transparent;color:var(--ink);cursor:pointer}.schedules button:disabled{opacity:.5;cursor:default}.schedules li{margin:8px 0}.actions{display:flex;flex-wrap:wrap;gap:12px}.schedule-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.schedule-grid>ul{list-style:none;padding:0}.availability-options summary{cursor:pointer;min-height:44px;padding:12px 0}.availability-preview{margin-top:40px;border-top:1px solid var(--line);padding-top:24px}.schedules :focus-visible{outline:2px solid var(--ink);outline-offset:3px}[role=alert]{color:#8b3429}@media(max-width:768px){.schedule-grid{grid-template-columns:1fr}}
</style>
